CREATE TABLE public.accommodations (
    id integer NOT NULL,
    spot_id integer NOT NULL,
    name character varying(255) NOT NULL,
    type character varying(50) NOT NULL,
    address text NOT NULL,
    phone character varying(20),
    price_min integer NOT NULL,
    price_max integer NOT NULL,
    rating numeric(2,1) DEFAULT 4.0,
    description text,
    amenities text[],
    website character varying(500),
    distance_miles numeric(4,1),
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT accommodations_type_check CHECK (((type)::text = ANY ((ARRAY['hotel'::character varying, 'motel'::character varying, 'airbnb'::character varying, 'lodge'::character varying, 'cabin'::character varying, 'resort'::character varying])::text[])))
);

CREATE SEQUENCE public.accommodations_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.accommodations_id_seq OWNED BY public.accommodations.id;



ALTER TABLE ONLY public.accommodations ALTER COLUMN id SET DEFAULT nextval('public.accommodations_id_seq'::regclass);

ALTER TABLE ONLY public.accommodations ADD CONSTRAINT accommodations_pkey PRIMARY KEY (id);

CREATE INDEX idx_accommodations_spot_id ON public.accommodations USING btree (spot_id);

SELECT setval('public.accommodations_id_seq', COALESCE(MAX(id), 1), MAX(id) IS NOT NULL) FROM public.accommodations;